 test(side+' Moonglow Reverse moves up to two counters from each ally onto a single target',()=>{const h=setup(side,'swsh11-74');try{h.us.active.damage=10;h.us.bench[0].damage=50;attack(h,'Moonglow Reverse');choice(h,a=>a.choiceOption===1);resolve(h);assert.equal(h.us.active.damage,0);assert.equal(h.us.bench[0].damage,30);assert.equal(h.them.active.damage,0);assert.equal(h.them.bench[0].damage,30);}finally{h.done();}});
