 test(side+' Spill Out discards whole hand and has a five-card damage threshold',()=>{for(const n of [4,5]){const h=setup(side,'swsh11-151');try{h.us.hand=Array.from({length:n},(_,i)=>ref('swsh11-1','spill'+i));attack(h,'Spill Out');resolve(h);assert.equal(h.them.active.damage,n===5?210:60);assert.equal(h.us.discard.filter(r=>r.uid.startsWith('spill')).length,n);}finally{h.done();}}});
 test(side+' Seething Currents shuffles only selected hand to deck bottom and draws four',()=>{for(const index of [0,1]){const h=setup(side,'swsh11-37');try{const board=index===0?h.us:h.them,other=index===0?h.them:h.us;board.hand=[ref('swsh11-1','old1'),ref('swsh11-2','old2')];other.hand=[ref('swsh11-4','untouched')];const deck=board.deck.map(r=>r.uid);use(h,'ability');choice(h,a=>a.choiceOption===index);resolve(h);assert.deepEqual(board.hand.map(r=>r.uid),deck.slice(0,4));assert.deepEqual(board.deck.slice(-2).map(r=>r.uid).sort(),['old1','old2']);assert.deepEqual(other.hand.map(r=>r.uid),['untouched']);}finally{h.done();}}});
 test(side+' Lost Shot routes opposing top card to its owner Lost Zone',()=>{const h=setup(side,'swsh11-111');try{const top=h.them.deck[0];attack(h,'Lost Shot');resolve(h);assert.ok(h.them.lostZone.some(r=>r.uid===top.uid));assert.ok(!h.them.discard.some(r=>r.uid===top.uid));assert.equal(h.them.active.damage,120);}finally{h.done();}});
 test(side+' Power Stone attaches actual Fighting Energy from hand',()=>{const h=setup(side,'swsh11-111');try{h.us.hand=[ref('dp1-128','fighting'),ref('dp1-125','water')];const before=h.us.active.energy.Fighting;attack(h,'Power Stone');resolve(h,a=>a.choiceTarget==='active'||!a.choiceSkip);assert.equal(h.us.active.energy.Fighting,before+1);assert.ok(h.us.hand.some(r=>r.uid==='water'));assert.ok(!h.us.hand.some(r=>r.uid==='fighting'));}finally{h.done();}});
 test(side+' Mischievous Tail offers skip and preserves opponent deck order when declined',()=>{const h=setup(side,'swsh11-144');try{const before=h.them.deck.map(r=>r.uid);attack(h,'Mischievous Tail');choice(h,a=>a.choiceOption===1);resolve(h);assert.deepEqual(h.them.deck.map(r=>r.uid),before.slice(1));assert.ok(h.them.hand.some(r=>r.uid===before[0]));}finally{h.done();}});
 test(side+' Fantina requires ten Lost Zone cards and protects the team against V on the next turn',()=>{const h=setup(side);try{h.us.lostZone=Array.from({length:9},(_,i)=>ref('swsh11-1','z'+i));h.us.hand=[ref('swsh11-157','fantina')];assert.ok(!core.legalActions(h.s,side).some(a=>a.type==='trainer'&&a.cardId==='swsh11-157'));h.us.lostZone.push(ref('swsh11-1','z9'));use(h,'trainer',a=>a.cardId==='swsh11-157');resolve(h);core.endTurn(h.s);resolve(h);h.them.active=slot('swsh11-92','v',{Fighting:3});assert.equal(fx.modifierAmount(h.s,side,h.us.active,'damageReduction',data.cardById),120);assert.equal(fx.modifierAmount(h.s,side,h.us.bench[0],'damageReduction',data.cardById),120);h.them.active.cardId='swsh11-86';assert.equal(fx.modifierAmount(h.s,side,h.us.active,'damageReduction',data.cardById),0);}finally{h.done();}});
