 test(side+' Field Trap discards only opposing Stadium and only then two Energy',()=>{for(const own of [true,false]){const h=setup(side,'swsh11-127');try{h.s.stadium={...ref('swsh11-161','stadium'),ownerSide:own?side:h.foe};h.them.active.energy={Water:3};attack(h,'Field Trap');resolve(h);assert.equal(h.them.active.energy.Water,own?3:1);assert.equal(!!h.s.stadium,own);assert.equal(h.them.discard.some(r=>r.uid==='stadium'),!own);}finally{h.done();}}});
 test(side+' Branch Calculation chooses either deck and reorders only its first four cards',()=>{const h=setup(side,'swsh11-140');try{const before=h.them.deck.map(r=>r.uid);const own=h.us.deck.map(r=>r.uid);attack(h,'Branch Calculation');choice(h,a=>a.choiceOption===1);for(const i of [3,2,1,0])choice(h,a=>a.choiceDeckIndex===i);resolve(h);assert.deepEqual(h.them.deck.map(r=>r.uid),[before[2],before[1],before[0],...before.slice(4)]);assert.deepEqual(h.us.deck.map(r=>r.uid),own);}finally{h.done();}});
 test(side+' All-You-Can-Grab flips until tails and can stop searching immediately',()=>{const h=setup(side,'swsh11-145');try{h.s.rngState=1;attack(h,'All-You-Can-Grab');const toss=h.s.log.find(x=>x.reason==='All-You-Can-Grab');assert.ok(toss);assert.equal(toss.results.at(-1),false);assert.equal(toss.results.slice(0,-1).every(Boolean),true);if(h.s.phase==='effectChoice')choice(h,a=>a.choiceSkip);resolve(h);assert.equal(h.us.hand.length,0);}finally{h.done();}});
 test(side+' Miss Fortune Sisters discards selected top-five Items, never deeper Items or Supporters',()=>{const h=setup(side);try{h.them.deck=[ref('swsh11-168','item1'),ref('swsh11-155','supporter'),ref('swsh11-162','item2'),ref('swsh11-1','poke'),ref('swsh11-161','stadium'),ref('swsh11-168','outside'),...h.them.deck];trainer(h,'swsh11-194');assert.deepEqual(core.legalActions(h.s,side).filter(a=>a.type==='effectChoice'&&!a.choiceSkip).map(a=>a.choiceDeckIndex),[0,2]);choice(h,a=>a.choiceDeckIndex===2);choice(h,a=>a.choiceSkip);resolve(h);assert.deepEqual(h.them.discard.map(r=>r.uid),['item2']);assert.ok(h.them.deck.some(r=>r.uid==='outside'));assert.ok(h.them.deck.some(r=>r.uid==='item1'));assert.ok(h.them.deck.some(r=>r.uid==='supporter'));}finally{h.done();}});
 test(side+' Lake Acuity protects both teams with Water or Fighting Energy, including applicable Special Energy',()=>{const h=setup(side);try{h.s.stadium={...ref('swsh11-160','lake'),ownerSide:side};h.us.active.energy={Fighting:1,Water:1};h.them.active.energy={Psychic:1};h.them.bench[0].specialEnergy=[ref('swsh4-165','wash')];assert.equal(fx.modifierAmount(h.s,side,h.us.active,'damageReduction',data.cardById),20);assert.equal(fx.modifierAmount(h.s,h.foe,h.them.active,'damageReduction',data.cardById),0);assert.equal(fx.modifierAmount(h.s,h.foe,h.them.bench[0],'damageReduction',data.cardById),20);h.s.stadium={...ref('swsh10-155','temple'),ownerSide:side};assert.equal(fx.modifierAmount(h.s,side,h.us.active,'damageReduction',data.cardById),0);}finally{h.done();}});
