for(const side of ['player','opponent']){
 test(side+' Chain of Spirits counts only own discarded Spiritomb across prints',()=>{const h=setup(side,'swsh11-117');try{h.us.active.energy={Darkness:2};h.us.discard=[ref('swsh11-117','one'),ref('swsh11-117','two'),ref('swsh11-1','other')];h.them.discard=[ref('swsh11-117','enemy')];h.us.lostZone=[ref('swsh11-117','lost')];attack(h,'Chain of Spirits');resolve(h);assert.equal(h.them.active.damage,130);}finally{h.done();}});
 test(side+' Cursed Message chooses physical card on opposing attack damage KO, respects suppression',()=>{for(const suppress of [false,true]){const h=setup(side,'swsh11-86');try{h.them.active=slot('swsh11-117','spirit');h.them.active.damage=50;h.them.deck=[ref('swsh11-155','pick'),ref('swsh11-1','rest'),ref('swsh11-1','rest2')];if(suppress)h.s.xy7HexManiacUntil=9;attack(h,'Punch');if(!suppress){assert.equal(h.s.choiceSide,h.foe);assert.equal(h.s.pendingChoice.kind,'deckCard');choice(h,a=>a.choiceDeckIndex===0);}resolve(h);assert.equal(h.them.hand.some(r=>r.uid==='pick'),!suppress);assert.ok(h.them.discard.some(r=>r.cardId==='swsh11-117'));}finally{h.done();}}});
 test(side+' Box of Disaster places 8 counters for either print only on full-HP Pokemon V attack-damage KO',()=>{for(const id of ['154','214'])for(const mode of ['full','damaged','nonV','suppressed']){const h=setup(side,'swsh11-3');try{h.us.active.cardId='swsh11-131';h.us.active.stack=['swsh11-130','swsh11-131'];h.us.active.energy={Grass:2,Psychic:2};h.them.active=slot(mode==='nonV'?'swsh11-86':'swsh11-92','boxTarget');h.them.active.tool=ref('swsh11-'+id,'box');h.them.active.damage=mode==='damaged'?10:0;if(mode==='suppressed')h.s.stadium={cardId:'sm6-111',ownerSide:side};attack(h,'Lost Impact');resolve(h);assert.equal(h.us.active.damage,mode==='full'?80:0,mode+' '+id);assert.ok(h.them.discard.some(r=>r.uid==='box'));assert.equal(h.s.log.filter(x=>x.type==='damageCounters'&&x.sourceCardId==='swsh11-'+id).length,mode==='full'?1:0);}finally{h.done();}}});
 test(side+' Tricky Slap resolves ties and guards against damage and effects only on win',()=>{const h=setup(side,'swsh11-67');try{h.s.rngState=1;attack(h,'Tricky Slap');assert.equal(h.s.choiceSide,'player');const original=h.us.active;resolve(h,a=>a.choiceOption===0);assert.equal(h.them.active.damage,90);const rounds=h.s.log.filter(x=>x.type==='rockPaperScissors'&&x.reason==='Tricky Slap');assert.ok(rounds.length);assert.ok(rounds.slice(0,-1).every(r=>r.result==='tie'));const win=rounds.at(-1).result==='win';assert.equal(!!fx.attackIsPrevented(h.s,side,original,h.them.active,data.cardById),win);assert.equal(!!fx.attackEffectsPrevented(h.s,side,original,h.them.active,data.cardById),win);}finally{h.done();}});
}
